terraform {
  required_version = ">= 1.6"
  required_providers {
    iosxe = {
      source  = "CiscoDevNet/iosxe"
      version = "~> 0.5"
    }
  }
  backend "http" {}   # GitLab-managed state; address and credentials come from CI variables
}

variable "iosxe_username" { type = string }
variable "iosxe_password" {
  type      = string
  sensitive = true
}

variable "vlans" {
  type = map(string)
  default = {
    "10" = "USERS"
    "30" = "VOICE"
  }
}

provider "iosxe" {
  username = var.iosxe_username
  password = var.iosxe_password
  url      = "https://10.20.1.11"
}

resource "iosxe_vlan" "vlan" {
  for_each = var.vlans
  vlan_id  = tonumber(each.key)
  name     = each.value
}

resource "iosxe_interface_loopback" "mgmt" {
  name              = 100
  description       = "Managed by Terraform"
  ipv4_address      = "192.0.2.11"
  ipv4_address_mask = "255.255.255.255"
}

